<?php $page = kimpu_homepage_source_page( 'kimpu_contact_source_page' ); ?><section class="section <?php echo esc_attr( kimpu_homepage_section_classes( 'contact' ) ); ?>" id="contact"><div class="container contact-grid"><div><?php kimpu_homepage_section_header( 'contact' ); ?><?php if ( $page ) : ?><div class="entry-content"><?php echo apply_filters( 'the_content', $page->post_content ); ?></div><?php endif; ?></div><div class="contact-details"><?php if ( get_theme_mod( 'kimpu_contact_email', '' ) ) : ?><p><strong><?php esc_html_e( 'Email', 'kimpu-multipurpose' ); ?></strong><br><a href="mailto:<?php echo esc_attr( sanitize_email( get_theme_mod( 'kimpu_contact_email' ) ) ); ?>"><?php echo esc_html( get_theme_mod( 'kimpu_contact_email' ) ); ?></a></p><?php endif; ?><?php if ( get_theme_mod( 'kimpu_contact_phone', '' ) ) : ?><p><strong><?php esc_html_e( 'Phone', 'kimpu-multipurpose' ); ?></strong><br><?php echo esc_html( get_theme_mod( 'kimpu_contact_phone' ) ); ?></p><?php endif; ?><?php if ( get_theme_mod( 'kimpu_contact_address', '' ) ) : ?><p><strong><?php esc_html_e( 'Address', 'kimpu-multipurpose' ); ?></strong><br><?php echo esc_html( get_theme_mod( 'kimpu_contact_address' ) ); ?></p><?php endif; ?><?php if ( get_theme_mod( 'kimpu_contact_hours', '' ) ) : ?><p><strong><?php esc_html_e( 'Working hours', 'kimpu-multipurpose' ); ?></strong><br><?php echo esc_html( get_theme_mod( 'kimpu_contact_hours' ) ); ?></p><?php endif; ?><?php if ( get_theme_mod( 'kimpu_contact_map_url', '' ) ) : ?><a class="button button-outline" href="<?php echo esc_url( get_theme_mod( 'kimpu_contact_map_url' ) ); ?>"><?php esc_html_e( 'Open map', 'kimpu-multipurpose' ); ?></a><?php endif; ?></div></div></section>
